 {filter&&!sections.some(s=>s.label.toLowerCase().includes(filter.toLowerCase()))&&<UI.Empty icon={<Search/>} title="No matching section" description="Try forms, agents, motion, or surfaces." action={<UI.Button onClick={()=>setFilter('')}>Clear search</UI.Button>}/>}
